@dataclass(frozen=True)
class ParallelCheckShardPlan:
	name: str
	checks: tuple[str, ...]
	execution_checks: tuple[str, ...]

	def to_dict(self) -> dict[str, Any]:
		return {
			"name": self.name,
			"checks": list(self.checks),
		}


@dataclass(frozen=True)
class ParallelShardCommandContract:
	"""Frozen declared/effective action identities captured before shard dispatch."""

	identities: Mapping[str, CommandIdentity]
	resolver_workspace: Path | None = None
	resolver_environment: Mapping[str, str] | None = None


def with_maintenance_process_authority(function: Callable[..., Any]) -> Callable[..., Any]:
	"""Give one direct action entry a single frozen authority for its full body."""
	@functools.wraps(function)
	def wrapped(*args: Any, **kwargs: Any) -> Any:
		if gf_process_authority.active_process_authority() is not None:
			return function(*args, **kwargs)
		authority = active_or_freeze_maintenance_process_authority()
		with gf_process_authority.activate_process_context(authority):
			return function(*args, **kwargs)

	return wrapped


@dataclass(frozen=True)
class PreparedParallelFullBatch:
	"""Own every materialized shard and frozen command contract before dispatch."""

	index: int
	plan: tuple[ParallelCheckShardPlan, ...]
	root: Path
	shards: tuple[ParallelShard, ...]
	report_paths: Mapping[str, Path]
	command_contracts: Mapping[str, ParallelShardCommandContract]
	cleanup_errors: list[str]


class ParallelFullBatchLease:
	"""Release one preflighted batch independently before later dispatch."""

	def __init__(
		self,
		path: Path,
		*,
		cleanup_state: dict[str, bool],
	) -> None:
		self.cleanup_errors: list[str] = []
		self._cleanup_state = cleanup_state
		self._manager = managed_owned_directory(
			path,
			cleanup_errors=self.cleanup_errors,
			cleanup_permitted=lambda: cleanup_state.get("permitted") is True,
			cleanup_started=lambda: cleanup_state.__setitem__("permitted", False),
			cleanup_succeeded=lambda: cleanup_state.__setitem__("permitted", True),
			cleanup_failed=lambda: cleanup_state.__setitem__("permitted", False),
			body_failed=lambda: cleanup_state.__setitem__("permitted", False),
		)
		self.root = self._manager.__enter__()
		self.active = True

	def release(self, error: BaseException | None = None) -> None:
		if not self.active:
			return
		self.active = False
		traceback = (
			None
			if error is None
			else BaseException.__getattribute__(error, "__traceback__")
		)
		suppressed = self._manager.__exit__(
			type(error) if error is not None else None,
			error,
			traceback,
		)
		if suppressed:
			raise WorkspaceSnapshotError(
				"Parallel Full batch owner unexpectedly suppressed an execution error."
			)


def release_parallel_full_batch_leases(
	leases: Sequence[ParallelFullBatchLease],
	*,
	error: BaseException | None = None,
) -> None:
	"""Release every still-active lease without abandoning later owner cleanup."""
	cleanup_failures: list[BaseException] = []
	for lease in reversed(leases):
		try:
			lease.release(error)
		except BaseException as cleanup_error:
			cleanup_failures.append(cleanup_error)
	if not cleanup_failures:
		return
	primary_cleanup_error = cleanup_failures[0]
	for cleanup_error in cleanup_failures[1:]:
		try:
			gf_process_supervisor.add_exception_note(
				primary_cleanup_error,
				"Additional parallel batch owner cleanup failed: "
				f"{type(cleanup_error).__name__}: "
				f"{gf_process_supervisor.safe_exception_detail(cleanup_error)}",
			)
		except BaseException:
			pass
	if error is not None:
		raise primary_cleanup_error from error
	raise primary_cleanup_error


def parallel_full_batch_cleanup_errors(
	leases: Sequence[ParallelFullBatchLease],
) -> list[str]:
	return [error for lease in leases for error in lease.cleanup_errors]


def raise_parallel_full_batch_cleanup_failure(
	leases: Sequence[ParallelFullBatchLease],
	*,
	log_copy_errors: Sequence[str],
) -> None:
	cleanup_errors = parallel_full_batch_cleanup_errors(leases)
	if not cleanup_errors:
		return
	details = [
		*(f"failure-log copy: {error}" for error in log_copy_errors),
		*(f"cleanup: {error}" for error in cleanup_errors),
	]
	raise WorkspaceSnapshotError(
		"Parallel Full batch cleanup failed; retained the owning validation "
		f"root for diagnosis: {'; '.join(details)}"
	)


def parallel_full_shard_plan(
	validation_plan: gf_validation_catalog.ValidationPlan,
) -> list[ParallelCheckShardPlan]:
	if validation_plan.suite != "full" or not validation_plan.lanes:
		raise ValueError("Parallel Full requires the canonical Full validation plan.")
	return [
		ParallelCheckShardPlan(
			name=lane.name,
			checks=lane.owned_actions,
			execution_checks=lane.execution_actions,
		)
		for lane in validation_plan.lanes
	]


def parallel_full_shard_batches(
	plan: list[ParallelCheckShardPlan],
	jobs: int,
) -> list[list[ParallelCheckShardPlan]]:
	"""Build stable resource-aware Full batches without changing shard ownership."""
	if jobs < 1:
		raise ValueError(f"Parallel Full batch size must be positive; got {jobs}.")
	batches: list[list[ParallelCheckShardPlan]] = []
	pending: list[ParallelCheckShardPlan] = []
	for shard in plan:
		if shard.name in PARALLEL_FULL_SINGLETON_SHARDS:
			if pending:
				batches.append(pending)
				pending = []
			batches.append([shard])
			continue
		pending.append(shard)
		if len(pending) == jobs:
			batches.append(pending)
			pending = []
	if pending:
		batches.append(pending)
	return batches


def parallel_shard_timeout_seconds(
	shard_plan: ParallelCheckShardPlan,
	requested_timeout_seconds: int | None,
	*,
	validation_catalog: gf_validation_catalog.ValidationCatalog,
) -> int:
	"""Budget the whole sequential child closure without weakening per-check minima."""
	closure_budget = sum(
		max(
			validation_catalog.timeout_floor_seconds(check_name),
			requested_timeout_seconds or 0,
		)
		for check_name in shard_plan.execution_checks
	)
	return max(
		PARALLEL_FULL_SHARD_TIMEOUT_SECONDS[shard_plan.name],
		closure_budget + PARALLEL_SHARD_STARTUP_ALLOWANCE_SECONDS,
	)


def resolve_check_jobs(
	suite: str,
	checks: list[str] | None,
	requested_jobs: int,
	*,
	sync_examples: bool = False,
) -> int:
	if requested_jobs < 0 or requested_jobs > MAX_PARALLEL_FULL_JOBS:
		raise ValueError(
			f"--jobs must be between 0 and {MAX_PARALLEL_FULL_JOBS}; got {requested_jobs}."
		)
	parallel_supported = suite == "full" and checks is None and not sync_examples
	if not parallel_supported:
		if requested_jobs > 1:
			raise ValueError(
				"Parallel check jobs are supported only for --suite full without --check or --sync-examples."
			)
		return 1
	if requested_jobs == 1:
		return 1
	if requested_jobs > 1:
		return requested_jobs
	return DEFAULT_PARALLEL_FULL_JOBS


def expanded_check_names(
	suite: str,
	checks: list[str] | None,
	*,
	sync_examples: bool = False,
) -> list[str]:
	return list(
		_VALIDATION_CATALOG.plan(
			suite,
			checks,
			sync_examples=sync_examples,
		).actions
	)


def package_artifact_is_required(check_names: list[str]) -> bool:
	return any(name in PACKAGE_ARTIFACT_CONSUMER_CHECKS for name in check_names)


DEFERRED_COMMAND_SENTINEL = "<deferred-command>"
UNRESOLVED_EXECUTABLE_SENTINEL = "<unresolved-executable>"
UNRESOLVED_GODOT_EXECUTABLE_SENTINEL = "<unresolved-godot-executable>"


class DeferredCommandMaterializationError(ValueError):
	"""Raised when a runner-owned deferred command cannot be materialized safely."""


@dataclass(frozen=True)
class DeferredCommandContext:
	"""Invocation-scoped live arguments available to deferred materializers."""

	artifact_manifest: str
	allow_breaking_api: bool


def release_metadata_command_contract(
	context: DeferredCommandContext,
) -> tuple[str, ...]:
	command = (
		sys.executable,
		"tools/gf_maintenance.py",
		"release-status",
		"--json",
		"--artifact-manifest",
		context.artifact_manifest,
	)
	return (*command, "--allow-breaking-api") if context.allow_breaking_api else command


def materialize_release_metadata_command(
	context: DeferredCommandContext,
) -> tuple[str, ...]:
	return release_metadata_command_contract(context)


def deferred_materialized_command_is_valid(
	name: str,
	command: tuple[object, ...],
	context: DeferredCommandContext,
) -> bool:
	if not command or any(type(part) is not str or "\x00" in part for part in command):
		return False
	if name == "release_metadata":
		return command == release_metadata_command_contract(context)
	return all(command)


def append_package_artifact_command_arguments(
	name: str,
	command: list[str],
	package_artifact_manifest: str,
	package_artifact_manifest_sha256: str,
) -> list[str]:
	if name not in PACKAGE_ARTIFACT_CONSUMER_CHECKS:
		return command
	if not package_artifact_inputs_are_complete(
		package_artifact_manifest,
		package_artifact_manifest_sha256,
	):
		raise PackageArtifactSetError(
			f"Package artifact inputs were not prepared for package consumer check: {name}"
		)
	return [
		*command,
		"--package-artifact-manifest",
		package_artifact_manifest,
		"--package-artifact-manifest-sha256",
		package_artifact_manifest_sha256,
	]


def fallback_check_command(
	name: str,
	package_artifact_manifest: str = "",
	package_artifact_manifest_sha256: str = "",
	*,
	validation_catalog: gf_validation_catalog.ValidationCatalog,
) -> list[str]:
	static_command = validation_catalog.static_command(name)
	command = (
		static_command
		if static_command is not None
		else [
			DEFERRED_COMMAND_SENTINEL,
			validation_catalog.executor_kind(name).value,
			name,
		]
	)
	if (
		name in PACKAGE_ARTIFACT_CONSUMER_CHECKS
		and not package_artifact_manifest
		and not package_artifact_manifest_sha256
	):
		return command
	return append_package_artifact_command_arguments(
		name,
		command,
		package_artifact_manifest,
		package_artifact_manifest_sha256,
	)


def materialize_check_command(
	name: str,
	package_artifact_manifest: str = "",
	package_artifact_manifest_sha256: str = "",
	*,
	validation_executor_binding: ValidationExecutorBinding,
	deferred_command_context: DeferredCommandContext,
) -> list[str]:
	static_command = validation_executor_binding.catalog.static_command(name)
	if static_command is None:
		try:
			materializer = validation_executor_binding.deferred_command_materializers[name]
		except KeyError as error:
			raise DeferredCommandMaterializationError(
				f"Deferred command materializer is missing for validation action: {name}"
			) from error
		try:
			materialized_command = materializer(deferred_command_context)
		except Exception as error:
			if exception_has_cleanup_debt(error):
				raise
			raise DeferredCommandMaterializationError(
				f"Deferred command materializer failed for validation action: {name}"
			) from error
		if (
			type(materialized_command) is not tuple
			or not deferred_materialized_command_is_valid(
				name,
				materialized_command,
				deferred_command_context,
			)
		):
			raise DeferredCommandMaterializationError(
				f"Deferred command materializer returned an invalid command for validation action: {name}"
			)
		command = list(materialized_command)
	else:
		command = static_command
	if DEFERRED_COMMAND_SENTINEL in command:
		raise DeferredCommandMaterializationError(
			f"Materialized command contains the deferred-command sentinel for validation action: {name}"
		)
	return append_package_artifact_command_arguments(
		name,
		command,
		package_artifact_manifest,
		package_artifact_manifest_sha256,
	)

_API_CACHE: list[ApiScript] | None = None
_ACTIVE_WORKSPACE_SNAPSHOT: WorkspaceSnapshot | None = None
_ACTIVE_SUITE_DEADLINE: float | None = None


@dataclass
class CommandResult:
	name: str
	command: list[str]
	exit_code: int
	stdout: str
	stderr: str
	timed_out: bool = False
	process_exit_code: int | None = None
	notes: list[str] | None = None
	godot_exit_leak_warnings: list[str] | None = None
	godot_exit_leak_report: dict[str, Any] | None = None
	gut_lifecycle_report: dict[str, Any] | None = None
	cwd: str = str(ROOT)
	duration_seconds: float = 0.0
	timeout_seconds: float | None = None
	execution: str = "subprocess"
	pid: int | None = None
	streamed_output: bool = False
	cancelled: bool = False

	def to_dict(
		self,
		max_output_chars: int | None = DEFAULT_COMMAND_RESULT_OUTPUT_CHARS,
	) -> dict[str, Any]:
		if max_output_chars is not None and (
			type(max_output_chars) is not int or max_output_chars < 0
		):
			raise ValueError("max_output_chars must be null or a non-negative integer")
		stdout_bytes = self.stdout.encode("utf-8")
		stderr_bytes = self.stderr.encode("utf-8")
		stdout_char_count = len(self.stdout)
		stderr_char_count = len(self.stderr)
		stdout_truncated = (
			max_output_chars is not None and stdout_char_count > max_output_chars
		)
		stderr_truncated = (
			max_output_chars is not None and stderr_char_count > max_output_chars
		)
		stdout_tail = self.stdout
		stderr_tail = self.stderr
		if stdout_truncated:
			stdout_tail = self.stdout[-max_output_chars:] if max_output_chars > 0 else ""
		if stderr_truncated:
			stderr_tail = self.stderr[-max_output_chars:] if max_output_chars > 0 else ""
		payload = {
			"name": self.name,
			"command": self.command,
			"cwd": self.cwd,
			"exit_code": self.exit_code,
			"timed_out": self.timed_out,
			"cancelled": self.cancelled,
			"duration_seconds": round(self.duration_seconds, 3),
			"execution": self.execution,
			# Keep stdout/stderr as the existing compatible tail fields while
			# binding each tail to evidence computed from the same captured text.
			"stdout": stdout_tail,
			"stderr": stderr_tail,
			"stdout_char_count": stdout_char_count,
			"stdout_utf8_byte_count": len(stdout_bytes),
			"stdout_sha256": hashlib.sha256(stdout_bytes).hexdigest(),
			"stdout_truncated": stdout_truncated,
			"stderr_char_count": stderr_char_count,
			"stderr_utf8_byte_count": len(stderr_bytes),
			"stderr_sha256": hashlib.sha256(stderr_bytes).hexdigest(),
			"stderr_truncated": stderr_truncated,
		}
		if self.timeout_seconds is not None:
			payload["timeout_seconds"] = self.timeout_seconds
		if self.pid is not None:
			payload["pid"] = self.pid
		if self.streamed_output:
			payload["streamed_output"] = True
		if self.process_exit_code != None and self.process_exit_code != self.exit_code:
			payload["process_exit_code"] = self.process_exit_code
		if self.notes:
			payload["notes"] = self.notes
		if self.godot_exit_leak_warnings:
			payload["godot_exit_leak_warning_count"] = len(self.godot_exit_leak_warnings)
			payload["godot_exit_leak_warnings"] = self.godot_exit_leak_warnings[:20]
		if self.godot_exit_leak_report:
			payload["godot_exit_leak_report"] = self.godot_exit_leak_report
		if self.gut_lifecycle_report:
			payload["gut_lifecycle_report"] = self.gut_lifecycle_report
		return payload


def make_unresolved_godot_command_result(
	name: str,
	declared_command: list[str],
	timeout_seconds: float,
	*,
	duration_seconds: float = 0.0,
) -> CommandResult:
	"""Report a Godot selection failure without presenting an effective argv."""
	return CommandResult(
		name=name,
		command=[
			UNRESOLVED_GODOT_EXECUTABLE_SENTINEL,
			*declared_command[1:],
		],
		exit_code=127,
		stdout="",
		stderr="Godot executable resolution failed before action dispatch.",
		notes=[
			"Install Godot or set GF_GODOT_EXECUTABLE to an existing executable path."
		],
		duration_seconds=duration_seconds,
		timeout_seconds=timeout_seconds,
		execution="not_started",
	)


def make_unresolved_command_result(
	name: str,
	declared_command: list[str],
	timeout_seconds: float,
	*,
	duration_seconds: float = 0.0,
) -> CommandResult:
	"""Report a generic executable selection failure before process dispatch."""
	return CommandResult(
		name=name,
		command=[
			UNRESOLVED_EXECUTABLE_SENTINEL,
			*declared_command[1:],
		],
		exit_code=127,
		stdout="",
		stderr="Executable resolution failed before action dispatch.",
		notes=[
			"Provide an existing executable through the frozen cwd/PATH search inputs."
		],
		duration_seconds=duration_seconds,
		timeout_seconds=timeout_seconds,
		execution="not_started",
	)


def add_package_artifact_consumer_arguments(parser: argparse.ArgumentParser) -> None:
	"""Add coordinator-owned immutable package artifact inputs to one command."""
	parser.add_argument(
		"--package-artifact-manifest",
		default="",
		help=argparse.SUPPRESS,
	)
	parser.add_argument(
		"--package-artifact-manifest-sha256",
		default="",
		help=argparse.SUPPRESS,
	)


def parse_gut_shard_run_timeout_seconds(text: str) -> int:
	"""Parse one CLI-only candidate timeout inside the worker phase ceiling."""
	maximum = gf_gut_shard_worker.MAX_PHASE_TIMEOUT_SECONDS
	try:
		value = int(text)
	except (TypeError, ValueError) as error:
		raise argparse.ArgumentTypeError(
			f"must be an integer between 1 and {maximum} seconds"
		) from error
	if not 1 <= value <= maximum:
		raise argparse.ArgumentTypeError(
			f"must be an integer between 1 and {maximum} seconds"
		)
	return value


def main() -> int:
	configure_stdio()
	maintenance_rendering.set_json_output_path(None)
	parser = argparse.ArgumentParser(description="GF maintenance helper CLI.")
	parser.add_argument(
		"--keep-logs",
		action="store_true",
		help=(
			"Retain logs produced by this invocation for diagnostics. May also be set with "
			f"{MAINTENANCE_KEEP_LOGS_ENV_VAR}=1."
		),
	)
	parser.add_argument(
		"--json-output",
		default="",
		help=(
			"Write the command result atomically as UTF-8 JSON below build/. "
			"This implies --json and avoids shell-dependent redirection encoding."
		),
	)
	subparsers = parser.add_subparsers(dest="command", required=True)

	summary_parser = subparsers.add_parser("summary", help="Print a compact project maintenance summary.")
	summary_parser.add_argument(
		"--release",
		action="store_true",
		help="Include release-status diagnostics. Requires --artifact-manifest for artifact validation.",
	)
	summary_parser.add_argument(
		"--artifact-manifest",
		default="",
		help="Prebuilt release artifact manifest used when --release is enabled.",
	)
	summary_parser.add_argument("--json", action="store_true", help="Print JSON instead of text.")

	search_parser = subparsers.add_parser("api-search", help="Search GF public API by class, member, path, or docs.")
	search_parser.add_argument("query", help="Search text.")
	search_parser.add_argument("--kind", choices=["all", "class", "member"], default="all")
	search_parser.add_argument("--limit", type=int, default=20)
	search_parser.add_argument("--json", action="store_true", help="Print JSON instead of text.")

	class_parser = subparsers.add_parser("api-class", help="Print one GF API class summary.")
	class_parser.add_argument("class_name", help="Class name, case-insensitive.")
	class_parser.add_argument("--json", action="store_true", help="Print JSON instead of text.")
	class_parser.add_argument("--no-members", action="store_true", help="Only print class-level information.")

	module_parser = subparsers.add_parser("api-module", help="Print a compact GF API module summary.")
	module_parser.add_argument("module", help="Module id such as kernel, standard, extensions/domain, or domain.")
	module_parser.add_argument("--members", action="store_true", help="Include compact public member signatures.")
	module_parser.add_argument("--limit", type=int, default=80, help="Maximum classes to return.")
	module_parser.add_argument("--json", action="store_true", help="Print JSON instead of text.")

	workspace_parser = subparsers.add_parser("workspace-status", help="Print categorized git status and suggested maintenance checks.")
	workspace_parser.add_argument(
		"--path",
		action="append",
		default=[],
		help="Limit the check recommendation plan to an explicit path. Can be passed multiple times.",
	)
	workspace_parser.add_argument("--json", action="store_true", help="Print JSON instead of text.")

	path_hygiene_parser = subparsers.add_parser("path-hygiene", help="Check tracked and untracked repository paths for cross-platform hazards.")
	path_hygiene_parser.add_argument("--json", action="store_true", help="Print JSON instead of text.")

	codeql_suppression_policy_parser = subparsers.add_parser(
		"codeql-suppression-policy",
		help="Audit exact test-only CodeQL suppressions and CodeQL configuration escape hatches.",
	)
	codeql_suppression_policy_parser.add_argument(
		"--json",
		action="store_true",
		help="Print JSON instead of text.",
	)

	api_since_touched_parser = subparsers.add_parser(
		"api-since-touched",
		help="Check changed public/protected API documentation blocks for @since tags.",
	)
	api_since_touched_parser.add_argument("--json", action="store_true", help="Print JSON instead of text.")

