def audit_resource_boundary_text(source: str, path: str) -> list[dict[str, Any]]:
	issues: list[dict[str, Any]] = []
	code_mask = gdscript_code_call_mask(source)
	for match in RESOURCE_LOAD_CALLEE_RE.finditer(code_mask):
		literal = parse_first_gdscript_string_argument(source, match.end())
		if literal is None:
			continue
		target = unescape_gdscript_string_literal(literal["value"])
		if not target.startswith(RESOURCE_BOUNDARY_DIRECT_PATH_PREFIXES):
			continue
		line_number = source.count("\n", 0, match.start()) + 1
		issues.append(make_resource_boundary_issue(
			path,
			line_number,
			match.group("callee"),
			target,
		))
	return issues


def make_resource_boundary_issue(path: str, line_number: int, callee: str, target: str) -> dict[str, Any]:
	extension = get_resource_target_extension(target)
	source_kind = resource_boundary_source_kind(path)
	if extension == ".gd":
		return make_boundary_issue(
			"direct_script_dependency_load",
			path,
			"Direct script preload/load is allowed for now but remains visible to resource-boundary audits.",
			line=line_number,
			severity="info",
			callee=callee,
			target=target,
			target_extension=extension,
			source_kind=source_kind,
		)
	if target in RESOURCE_BOUNDARY_EDITOR_METADATA_TARGETS:
		return make_boundary_issue(
			"direct_editor_metadata_load",
			path,
			"Editor/plugin metadata load literals are tracked separately from runtime resource loads.",
			line=line_number,
			severity="info",
			callee=callee,
			target=target,
			target_extension=extension,
			source_kind=source_kind,
		)
	if (
		source_kind == "test"
		and is_normalized_test_owned_path(path)
		and is_normalized_test_fixture_resource_path(target)
	):
		return make_boundary_issue(
			"direct_test_fixture_resource_load",
			path,
			"Test-owned fixture resource loads remain visible without imposing runtime resource-domain policy.",
			line=line_number,
			severity="info",
			callee=callee,
			target=target,
			target_extension=extension,
			source_kind=source_kind,
		)
	if target.startswith("user://"):
		return make_boundary_issue(
			"direct_user_resource_load",
			path,
			"user:// resource load literals are report-only for now; runtime ownership should still be explicit.",
			line=line_number,
			severity="info",
			callee=callee,
			target=target,
			target_extension=extension,
			source_kind=source_kind,
		)
	if target.startswith("uid://"):
		return make_boundary_issue(
			"direct_uid_resource_load",
			path,
			"UID resource load literals bypass stable GF resource keys and should be reviewed before strict mode.",
			line=line_number,
			severity="warning",
			callee=callee,
			target=target,
			target_extension=extension,
			source_kind=source_kind,
		)
	return make_boundary_issue(
		"direct_resource_path_load",
		path,
		"Direct resource path load literals should move toward GFResourceResolverUtility keys or declared resource domains.",
		line=line_number,
		severity="warning",
		callee=callee,
		target=target,
		target_extension=extension,
		source_kind=source_kind,
	)


def is_normalized_test_owned_path(path: str) -> bool:
	normalized_path = path.replace("\\", "/")
	parts = normalized_path.split("/")
	if ".." in parts:
		return False
	return posixpath.normpath(normalized_path).startswith("tests/gf_core/")


def is_normalized_test_fixture_resource_path(target: str) -> bool:
	if not target.startswith("res://"):
		return False
	resource_path = target[len("res://"):]
	parts = resource_path.split("/")
	if ".." in parts:
		return False
	return posixpath.normpath(resource_path).startswith("tests/gf_core/")


def resource_boundary_source_kind(path: str) -> str:
	normalized_path = path.replace("\\", "/")
	if normalized_path.startswith("tests/"):
		return "test"
	if normalized_path.startswith("addons/gf/tools/"):
		return "tool"
	if (
		normalized_path.startswith("addons/gf/kernel/editor/")
		or normalized_path.startswith("addons/gf/standard/editor/")
		or "/editor/" in normalized_path
	):
		return "editor"
	if normalized_path.startswith("addons/gf/"):
		return "runtime"
	return "other"


def resource_boundary_source_package(
	path: str,
	owner_entries: list[dict[str, str]] | PackageOwnershipIndex,
) -> str:
	normalized_path = normalize_package_manifest_path(path)
	if not normalized_path:
		return "<other>"
	if normalized_path.startswith("tests/"):
		return "<test>"
	if not normalized_path.startswith("addons/gf/"):
		return "<other>"
	owner = find_package_source_owner(normalized_path, owner_entries)
	if owner:
		return owner["package_id"]
	if not owner_entries:
		return "<unknown>"
	return "<unowned>"


def resource_boundary_target_package(
	target: str,
	owner_entries: list[dict[str, str]] | PackageOwnershipIndex,
) -> str:
	normalized_target = target.strip().replace("\\", "/")
	if normalized_target.startswith("uid://"):
		return "<uid>"
	if normalized_target.startswith("user://"):
		return "<user>"
	if normalized_target.startswith("res://"):
		target_path = normalize_package_manifest_path(normalized_target.removeprefix("res://"))
		if not target_path:
			return "<other>"
		if not target_path.startswith("addons/gf/"):
			return "<project>"
		owner = find_package_source_owner(target_path, owner_entries)
		if owner:
			return owner["package_id"]
		if not owner_entries:
			return "<unknown>"
		return "<unowned>"
	return "<other>"


def count_issue_field(issues: list[dict[str, Any]], field_name: str) -> list[dict[str, Any]]:
	counter: dict[str, int] = {}
	for issue in issues:
		key = str(issue.get(field_name) or "<empty>")
		increment_counter(counter, key)
	return counter_items(counter)


def count_issue_field_pair(
	issues: list[dict[str, Any]],
	left_field_name: str,
	right_field_name: str,
) -> list[dict[str, Any]]:
	counter: dict[tuple[str, str], int] = {}
	for issue in issues:
		left_value = str(issue.get(left_field_name, ""))
		right_value = str(issue.get(right_field_name, ""))
		if not left_value or not right_value:
			continue
		key = (left_value, right_value)
		counter[key] = counter.get(key, 0) + 1
	return [
		{
			"key": f"{left_value} -> {right_value}",
			"source": left_value,
			"target": right_value,
			"count": count,
		}
		for (left_value, right_value), count in sorted(
			counter.items(),
			key=lambda item: (-item[1], item[0][0], item[0][1]),
		)
	]


def count_record_field(records: list[dict[str, Any]], field_name: str) -> list[dict[str, Any]]:
	counter: dict[str, int] = {}
	for record in records:
		key = str(record.get(field_name) or "<empty>")
		increment_counter(counter, key)
	return counter_items(counter)


def gdscript_code_call_mask(source: str) -> str:
	result: list[str] = []
	in_string = False
	string_quote = ""
	escaped = False
	in_comment = False
	for character in source:
		if in_comment:
			if character == "\n":
				in_comment = False
				result.append("\n")
			else:
				result.append(" ")
			continue
		if in_string:
			if escaped:
				escaped = False
			elif character == "\\":
				escaped = True
			elif character == string_quote:
				in_string = False
				string_quote = ""
			result.append("\n" if character == "\n" else " ")
			continue
		if character == "#":
			in_comment = True
			result.append(" ")
			continue
		if character in ("'", '"'):
			in_string = True
			string_quote = character
			result.append(" ")
			continue
		result.append(character)
	return "".join(result)


def parse_first_gdscript_string_argument(source: str, start_index: int) -> dict[str, str] | None:
	index = skip_gdscript_argument_whitespace(source, start_index)
	if index >= len(source) or source[index] not in ("'", '"'):
		return None
	quote = source[index]
	index += 1
	value_parts: list[str] = []
	escaped = False
	while index < len(source):
		character = source[index]
		if escaped:
			value_parts.append("\\" + character)
			escaped = False
			index += 1
			continue
		if character == "\\":
			escaped = True
			index += 1
			continue
		if character == quote:
			return {"value": "".join(value_parts)}
		value_parts.append(character)
		index += 1
	return None


def skip_gdscript_argument_whitespace(source: str, start_index: int) -> int:
	index = start_index
	while index < len(source):
		character = source[index]
		if character.isspace():
			index += 1
			continue
		if character == "#":
			while index < len(source) and source[index] != "\n":
				index += 1
			continue
		return index
	return index


def strip_gdscript_line_comment(line: str) -> str:
	in_string = False
	string_quote = ""
	escaped = False
	for index, character in enumerate(line):
		if escaped:
			escaped = False
			continue
		if in_string and character == "\\":
			escaped = True
			continue
		if character in ("'", '"'):
			if not in_string:
				in_string = True
				string_quote = character
				continue
			if character == string_quote:
				in_string = False
				string_quote = ""
				continue
		if character == "#" and not in_string:
			return line[:index]
	return line


def strip_gdscript_comments(source: str) -> str:
	result: list[str] = []
	index = 0
	state = "code"
	delimiter = ""
	while index < len(source):
		if state == "comment":
			character = source[index]
			if character == "\n":
				result.append(character)
				state = "code"
			else:
				result.append(" ")
			index += 1
			continue

		if state == "string":
			if source.startswith(delimiter, index):
				result.append(delimiter)
				index += len(delimiter)
				state = "code"
				continue
			character = source[index]
			result.append(character)
			if character == "\\" and index + 1 < len(source):
				result.append(source[index + 1])
				index += 2
				continue
			index += 1
			continue

		if source.startswith("'''", index) or source.startswith('\"\"\"', index):
			delimiter = source[index:index + 3]
			result.append(delimiter)
			index += 3
			state = "string"
			continue
		character = source[index]
		if character in ("'", '"'):
			delimiter = character
			result.append(character)
			index += 1
			state = "string"
			continue
		if character == "#":
			result.append(" ")
			index += 1
			state = "comment"
			continue
		result.append(character)
		index += 1
	return "".join(result)


def gdscript_position_is_code(line: str, target_index: int) -> bool:
	in_string = False
	string_quote = ""
	escaped = False
	for index, character in enumerate(line):
		if index >= target_index:
			return not in_string
		if escaped:
			escaped = False
			continue
		if in_string and character == "\\":
			escaped = True
			continue
		if character in ("'", '"'):
			if not in_string:
				in_string = True
				string_quote = character
				continue
			if character == string_quote:
				in_string = False
				string_quote = ""
				continue
		if character == "#" and not in_string:
			return False
	return not in_string


def unescape_gdscript_string_literal(value: str) -> str:
	return value.replace(r"\/", "/").replace(r"\'", "'").replace(r"\"", '"')


def get_resource_target_extension(target: str) -> str:
	normalized_target = target.split("?", 1)[0].split("#", 1)[0].rstrip("/")
	file_name = normalized_target.rsplit("/", 1)[-1]
	if "." not in file_name:
		return ""
	return "." + file_name.rsplit(".", 1)[1].lower()


def collect_text_files(root: Path, extensions: set[str]) -> list[Path]:
	def scan() -> list[Path]:
		if not root.is_dir():
			return []
		return [
			path
			for path in sorted(root.rglob("*"))
			if path.is_file() and path.suffix.lower() in extensions
		]

	if _ACTIVE_WORKSPACE_SNAPSHOT is None:
		return scan()
	return _ACTIVE_WORKSPACE_SNAPSHOT.memoize(
		"collect_text_files",
		(str(root), tuple(sorted(extensions))),
		scan,
	)


def collect_class_name_roots(root: Path) -> dict[str, str]:
	result: dict[str, str] = {}
	for path in collect_text_files(root, {".gd"}):
		text = read_text_file(path)
		for match in re.finditer(r"(?m)^\s*class_name\s+([A-Za-z_]\w*)", text):
			result[match.group(1)] = path.relative_to(ROOT).as_posix()
	return result


def extract_bundled_extension_names(source: str) -> list[str]:
	names: list[str] = []
	for match in re.finditer(r"(?:res://)?addons/gf/extensions/([A-Za-z0-9_.-]+)", source):
		name = match.group(1).strip()
		if name and name not in names:
			names.append(name)
	return names


def source_contains_bare_bundled_extension_root(source: str) -> bool:
	return re.search(
		r"(?:res://)?addons/gf/extensions(?=[\"'`\s),\]}]|$)",
		source,
	) is not None


def get_bundled_extension_name_from_relative_path(path: str) -> str:
	normalized_path = path.replace("\\", "/")
	prefix = "addons/gf/extensions/"
	if not normalized_path.startswith(prefix):
		return ""
	remaining = normalized_path[len(prefix):]
	if "/" not in remaining:
		return ""
	return remaining.split("/", 1)[0].strip()


def source_contains_identifier(source: str, identifier: str) -> bool:
	return identifier in source_identifiers(source)


def source_identifiers(source: str) -> frozenset[str]:
	def tokenize() -> frozenset[str]:
		return frozenset(match.group(1) for match in SOURCE_IDENTIFIER_RE.finditer(source))

	if _ACTIVE_WORKSPACE_SNAPSHOT is None:
		return tokenize()
	return _ACTIVE_WORKSPACE_SNAPSHOT.memoize(
		"source_identifier_tokens",
		source,
		tokenize,
	)


def read_text_file(path: Path) -> str:
	try:
		if _ACTIVE_WORKSPACE_SNAPSHOT is not None:
			return _ACTIVE_WORKSPACE_SNAPSHOT.read_utf8_text(path)
		return path.read_text(encoding="utf-8")
	except OSError:
		return ""


def make_boundary_issue(
	kind: str,
	path: str,
	message: str,
	**extra: Any,
) -> dict[str, Any]:
	issue = {
		"kind": kind,
		"path": path,
		"message": message,
	}
	issue.update({key: value for key, value in extra.items() if value not in ("", None)})
	return issue


def read_git_paths(
	command: list[str],
	*,
	strict_utf8: bool = False,
) -> dict[str, Any]:
	if _ACTIVE_WORKSPACE_SNAPSHOT is not None:
		return _ACTIVE_WORKSPACE_SNAPSHOT.memoize(
			"git_paths",
			(tuple(command), strict_utf8),
			lambda: read_git_paths_uncached(command, strict_utf8=strict_utf8),
		)
	return read_git_paths_uncached(command, strict_utf8=strict_utf8)


def run_frozen_maintenance_git(
	arguments: Sequence[str],
	*,
	binary_output: bool = False,
) -> Any:
	"""Dispatch Git only through one frozen absolute invocation capability."""
	git_process = active_or_freeze_maintenance_process_authority().git
	command = list(git_process.command(arguments).effective)
	try:
		result = run_supervised_process(
			command,
			cwd=ROOT,
			timeout_seconds=30.0,
			environment=git_process.environment.values(),
			binary_output=binary_output,
			text_errors="replace",
		)
	except gf_process_supervisor.SupervisedProcessStartError as error:
		raise error.original_error from error
	if result.process_boundary_quiescent is not True:
		raise gf_parallel_validation.WorkspaceProcessBoundaryError(
			"Maintenance Git process-boundary cleanup was not proven."
		)
	if result.timed_out:
		raise subprocess.TimeoutExpired(
			command,
			30.0,
			output=result.stdout,
			stderr=result.stderr,
		)
	return result


def read_git_paths_uncached(
	command: list[str],
	*,
	strict_utf8: bool = False,
) -> dict[str, Any]:
	result = run_frozen_maintenance_git(command, binary_output=True)
	if result.return_code != 0:
		stderr = result.stderr if isinstance(result.stderr, bytes) else result.stderr.encode("utf-8")
		stdout = result.stdout if isinstance(result.stdout, bytes) else result.stdout.encode("utf-8")
		message = (stderr or stdout).decode("utf-8", errors="replace").strip()
		return {"paths": [], "error": message or "git path scan failed."}
	stdout = result.stdout if isinstance(result.stdout, bytes) else result.stdout.encode("utf-8")
	try:
		decoded_stdout = stdout.decode(
			"utf-8",
			errors="strict" if strict_utf8 else "replace",
		)
	except UnicodeDecodeError:
		return {
			"paths": [],
			"error": "Git path inventory is not valid UTF-8.",
		}
	raw_paths = [path for path in decoded_stdout.split("\0") if path]
	if strict_utf8 and any(
		"\\" in path
		or path.startswith("/")
		or re.match(r"^[A-Za-z]:", path) is not None
		or any(part in ("", ".", "..") for part in path.split("/"))
		or any(ord(character) < 0x20 or ord(character) == 0x7F for character in path)
		for path in raw_paths
	):
		return {
			"paths": [],
			"error": "Git path inventory contains a non-canonical path.",
		}
	paths = sorted({
		path if strict_utf8 else path.replace("\\", "/")
		for path in raw_paths
	})
	return {"paths": paths, "error": ""}


def find_case_collision_issues(tracked_paths: list[str]) -> list[dict[str, Any]]:
	paths_by_folded_name: dict[str, list[str]] = {}
	for path in tracked_paths:
		paths_by_folded_name.setdefault(path.casefold(), []).append(path)

	issues: list[dict[str, Any]] = []
	for folded_path, paths in sorted(paths_by_folded_name.items()):
		unique_paths = sorted(set(paths))
		if len(unique_paths) <= 1:
			continue
		issues.append({
			"kind": "case_collision",
			"path": folded_path,
			"paths": unique_paths,
			"message": "Tracked paths differ only by case and may overwrite each other on case-insensitive filesystems.",
		})
	return issues


def find_blocked_tracked_dir_issues(tracked_paths: list[str]) -> list[dict[str, Any]]:
	blocked_names = set(BLOCKED_PACKAGE_DIR_NAMES)
	blocked_paths: set[str] = set()
	for path in tracked_paths:
		parts = path.split("/")
		for index, part in enumerate(parts[:-1]):
			if part in blocked_names:
				blocked_paths.add("/".join(parts[:index + 1]))

	return [
		{
			"kind": "blocked_tracked_directory",
			"path": path,
			"message": "Tracked files live inside a cache or dependency directory that should not ship with GF.",
		}
		for path in sorted(blocked_paths)
	]


def find_missing_local_github_action_issues(scanned_paths: list[str]) -> list[dict[str, Any]]:
	scanned_path_set = set(scanned_paths)
	workflow_paths = [
		path for path in scanned_paths
		if path.startswith(".github/workflows/")
		and Path(path).suffix.lower() in {".yml", ".yaml"}
	]
	issues: list[dict[str, Any]] = []
	for workflow_path in workflow_paths:
		source = read_text_file(ROOT / workflow_path)
		for line_number, line in enumerate(source.splitlines(), start=1):
			match = re.search(r"\buses:\s*['\"]?(\./\.github/actions/[A-Za-z0-9_.\-/]+)['\"]?", line)
			if match is None:
				continue
			action_path = match.group(1).removeprefix("./").rstrip("/")
			action_manifest_path = f"{action_path}/action.yml"
			if action_manifest_path in scanned_path_set or (ROOT / action_manifest_path).is_file():
				continue
			issues.append({
				"kind": "missing_local_github_action_manifest",
				"path": workflow_path,
				"line": line_number,
				"message": f"Workflow references {match.group(1)} but {action_manifest_path} is missing.",
			})
	return issues


def find_gdscript_text_format_issues(scanned_paths: list[str]) -> list[dict[str, Any]]:
	issues: list[dict[str, Any]] = []
	for path in scanned_paths:
		if (
			not path.endswith(".gd")
			or not path.startswith(("addons/gf/", "tests/gf_core/"))
		):
			continue
		source_path = ROOT / path
		if not source_path.is_file():
			continue
		try:
			data = source_path.read_bytes()
		except OSError as exc:
			issues.append({
				"kind": "gdscript_source_unreadable",
				"path": path,
				"message": f"Could not read GDScript source while checking encoding: {exc}",
			})
			continue
		issues.extend(audit_gdscript_text_format(path, data))
	return issues


def audit_gdscript_text_format(path: str, data: bytes) -> list[dict[str, Any]]:
	issues: list[dict[str, Any]] = []
	if has_utf8_bom(data):
		issues.append({
			"kind": "gdscript_utf8_bom",
			"path": path,
			"message": "GDScript files must be UTF-8 without BOM.",
		})
		return issues
	try:
		source = data.decode("utf-8", errors="strict")
	except UnicodeDecodeError as exc:
		return [{
			"kind": "gdscript_invalid_utf8",
			"path": path,
			"message": f"GDScript source is not strict UTF-8: {exc.reason}.",
		}]
	if b"\r" in data:
		issues.append({
			"kind": "gdscript_non_lf_line_ending",
			"path": path,
			"message": "GDScript files must use LF line endings.",
		})
	if data and not data.endswith(b"\n"):
		issues.append({
			"kind": "gdscript_missing_final_newline",
			"path": path,
			"message": "GDScript files must end with one LF newline.",
		})
	raw_lines = source.splitlines()
	_structural_lines, starts_in_multiline = scan_gdscript_structure(raw_lines)
	for line_number, line in enumerate(raw_lines, start=1):
		if line.startswith(" ") and not starts_in_multiline[line_number - 1]:
			issues.append({
				"kind": "gdscript_space_indentation",
				"path": path,
				"line": line_number,
				"message": "GDScript indentation must use tabs; leading spaces are allowed only inside multiline strings.",
			})
	return issues


def has_utf8_bom(data: bytes) -> bool:
	return data.startswith(b"\xef\xbb\xbf")


def parse_git_status(lines: list[str]) -> list[dict[str, str]]:
	entries: list[dict[str, str]] = []
	for line in lines:
		if len(line) < 3:
			continue
		status = line[:2]
		path = line[3:].strip()
		if " -> " in path:
			path = path.split(" -> ", 1)[1].strip()
		entries.append({
			"status": status,
			"path": path.replace("\\", "/"),
		})
	return entries


def classify_status_path(path: str) -> str:
	normalized = path.replace("\\", "/")
	if normalized.startswith("docs/api_catalog/") or normalized.startswith("docs/zh/reference/api/"):
		return "generated_docs"
	if normalized.startswith("examples/"):
		return "examples"
	if normalized.startswith("tests/"):
		return "tests"
	if normalized.startswith("docs/") or normalized in {"README.md", "README.zh.md", "addons/gf/README.md", "mkdocs.yml"}:
		return "manual_docs"
	if (
		normalized.startswith(".codex/")
		or normalized.startswith(".github/")
		or normalized.startswith("tools/")
		or normalized.startswith("packages/")
		or normalized in {"AI_MAINTENANCE.md", "CODING_STYLE.md", "API_SURFACE.md", "CONTRIBUTING.md"}
		or normalized in PROJECT_PROFILE_DEFAULT_FILES
	):
		return "maintenance_tools"
	if (
		normalized in {"ASSET_LIBRARY.md", "ASSET_STORE.md", ".gitattributes"}
		or normalized == "addons/gf/plugin.cfg"
		or normalized.endswith("/gf_extension.json")
	):
		return "release_metadata"
	if normalized.startswith("addons/gf/tools/"):
		return "tool_source"
	if normalized.startswith("addons/gf/"):
		return "runtime_source"
	return "other"


def recommend_checks(categories: dict[str, list[dict[str, str]]]) -> list[str]:
	recommendations: list[str] = []
	if categories["runtime_source"] or categories["tool_source"]:
		recommendations.extend([
			"python tools/generate_api_reference.py --check",
			"python tools/generate_ai_api.py --source addons/gf --output ai_analysis/generated_api --check-or-generate --check-wiki-coverage",
			"python tools/gf_maintenance.py public-api-boundary --json",
			"python tools/gf_maintenance.py api-since-touched --json",
			"python tools/gf_maintenance.py check --check gut --failed-only",
			"python tools/gf_maintenance.py check --check gdscript_warnings --json",
			"python tools/gf_maintenance.py check --check gdscript_lsp_diagnostics --json",
			"python tools/gf_maintenance.py dependency-boundary --json",
			"python tools/gf_maintenance.py resource-boundary --json",
			"python tools/gf_maintenance.py content-package-boundary --json",
			"python tools/gf_maintenance.py asset-lifecycle-boundary --json",
			"python tools/gf_maintenance.py project-profile-boundary --json",
			"python tools/gf_maintenance.py check --suite package --json",
			"python tools/gf_maintenance.py package-godot-smoke --json",
		])
	if categories["examples"]:
		recommendations.append("python tools/gf_maintenance.py check --suite examples --json")
	if categories["tests"]:
		recommendations.extend([
			"python tools/gf_maintenance.py check --check gut --failed-only",
			"python tools/gf_maintenance.py check --check gdscript_lsp_diagnostics --json",
		])
	if categories["manual_docs"]:
		recommendations.extend([
			"python tools/check_docs_quality.py --strict",
			"python tools/gf_maintenance.py public-docs-boundary --json",
			"python -m mkdocs build --strict",
		])
	if categories["generated_docs"]:
		recommendations.append("python tools/generate_api_reference.py --check")
		recommendations.append("python tools/gf_maintenance.py public-api-boundary --json")
		recommendations.append("python tools/gf_maintenance.py api-baseline-diff --json")
	if categories["maintenance_tools"]:
		recommendations.extend([
			(
				"python -m py_compile tools/gf_maintenance.py tools/gf_maintenance_self_test.py "
				"tools/gf_mcp_server.py "
				"tools/gf_validation_catalog.py "
				"tools/gf_project_layout_profile.py "
				"tools/gf_executable_resolution.py tools/gf_godot_process.py "
				"tools/gf_process_authority.py "
				"tools/gf_package_artifact_set.py tools/gf_package_paths.py "
				"tools/gf_parallel_validation.py tools/gf_process_supervisor.py "
				"tools/gf_repository_policy.py tools/gf_semver.py tools/gf_workspace_snapshot.py"
			),
			"python tools/gf_maintenance.py maintenance-self-test --json",
			"python tools/gf_maintenance.py check --suite quick --json",
		])
		if has_package_maintenance_paths(categories["maintenance_tools"]):
			recommendations.extend([
				"python tools/gf_maintenance.py check --suite package --json",
				"python tools/gf_maintenance.py package-godot-smoke --json",
				"python tools/gf_maintenance.py check --check package_godot_matrix_smoke --json",
			])
		if has_repository_policy_paths(categories["maintenance_tools"]):
			recommendations.append("python tools/gf_repository_policy.py validate --json")
	if categories["release_metadata"]:
		release_version = read_plugin_version()
		if SEMVER_RE.fullmatch(release_version):
			release_manifest = f"build/release/gf-release-artifacts-{release_version}.json"
			recommendations.append(
				f"python tools/build_gf_release_artifacts.py --version {release_version} --output-dir build/release"
			)
			recommendations.append(
				"python tools/gf_maintenance.py release-status "
				f"--version {release_version} --artifact-manifest {release_manifest} --json"
			)
			recommendations.append("python tools/gf_maintenance.py api-baseline-diff --json")
		else:
			recommendations.append("python tools/gf_repository_policy.py validate --json")
			recommendations.append("python tools/build_gf_ai_developer_kit.py --check-source --json")
		recommendations.append("python tools/gf_maintenance.py dependency-boundary --json")
		recommendations.append("python tools/gf_maintenance.py content-package-boundary --json")
		recommendations.append("python tools/gf_maintenance.py project-profile-boundary --json")
		recommendations.append("python tools/gf_maintenance.py check --suite package --json")
		recommendations.append("python tools/gf_maintenance.py check --check package_godot_matrix_smoke --json")
		recommendations.append("python tools/gf_maintenance.py public-docs-boundary --json")
	if categories["other"]:
		recommendations.append("python tools/gf_maintenance.py check --suite quick --json")
	return dedupe_preserve_order(recommendations)


def has_package_maintenance_paths(entries: list[dict[str, str]]) -> bool:
	package_paths = {
		"tools/build_gf_package.py",
		"tools/build_gf_release_artifacts.py",
		"tools/gf_package_artifact_set.py",
		"tools/gf_path_security.py",
		"tools/gf_package_resolver.py",
		"tools/gf_semver.py",
	}
	for entry in entries:
		path = entry["path"]
		if path in package_paths or path.startswith("packages/"):
			return True
	return False


def has_repository_policy_paths(entries: list[dict[str, str]]) -> bool:
	governed_paths = {
		".github/repository-policy.json",
		"tools/gf_repository_policy.py",
	}
	return any(
		entry["path"] in governed_paths
		or entry["path"].startswith(".github/workflows/")
		for entry in entries
	)


def dedupe_preserve_order(items: list[str]) -> list[str]:
	result: list[str] = []
	for item in items:
		if item not in result:
			result.append(item)
	return result


def load_api_scripts() -> list[ApiScript]:
	global _API_CACHE
	if _API_CACHE is None:
		_API_CACHE = collect_api_scripts(ROOT / "addons/gf", ROOT)
	return _API_CACHE


def invalidate_api_cache() -> None:
	"""Discard request-scoped API source data before serving a new caller."""
	global _API_CACHE
	_API_CACHE = None


def all_members(script: ApiScript) -> list[ApiMember]:
	return [*script.signals, *script.enums, *script.constants, *script.properties, *script.methods]


def score_member(needle: str, member: ApiMember) -> int:
	score = score_text(needle, member.name, exact=100, starts=80, contains=60)
	score = max(score, score_text(needle, member.signature, exact=60, starts=50, contains=40))
	score = max(score, score_text(needle, " ".join(docs_to_lines(member.docs)), exact=30, starts=20, contains=10))
	return score


def score_text(needle: str, value: str, exact: int, starts: int, contains: int) -> int:
	text = value.lower()
	if not text:
		return 0
	if text == needle:
		return exact
	if text.startswith(needle):
		return starts
	if needle in text:
		return contains
	return 0


def docs_to_lines(docs: ApiDocs) -> list[str]:
	lines = docs.description[:]
	for tag_name in sorted(docs.tags):
		for value in docs.tags[tag_name]:
			lines.append(f"@{tag_name} {value}".strip())
	return lines


def docs_summary(docs: ApiDocs, max_lines: int = 3) -> list[str]:
	return docs_to_lines(docs)[:max_lines]


def member_to_compact_dict(member: ApiMember, score: int) -> dict[str, Any]:
	return {
		"score": score,
		"kind": member.kind,
		"name": member.name,
		"signature": member.signature,
		"docs": docs_summary(member.docs, max_lines=2),
	}


def member_to_module_dict(member: ApiMember) -> dict[str, Any]:
	return {
		"kind": member.kind,
		"name": member.name,
		"signature": member.signature,
		"docs": docs_summary(member.docs, max_lines=2),
	}


def member_to_dict(member: ApiMember) -> dict[str, Any]:
	return {
		"kind": member.kind,
		"name": member.name,
		"signature": member.signature,
		"line": member.line,
		"decorators": member.decorators,
		"docs": docs_to_lines(member.docs),
	}


